-- VEGA Exhibition CRM/ERP base schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','accountant','staff');
create type public.record_status as enum ('draft','active','confirmed','cancelled','completed','overdue');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', email text not null default '', role public.app_role not null default 'staff', created_at timestamptz not null default now());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid(); $$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_role()='admin',false); $$;
create table public.exhibitions(id uuid primary key default gen_random_uuid(), name text not null, venue text, city text, country text, start_date date, end_date date, currency char(3) not null default 'AED', status public.record_status not null default 'draft', description text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.exhibitors(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id) on delete set null, company_name text not null, contact_name text, email text, phone text, whatsapp text, country text, category text, lead_source text, status text not null default 'lead', notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.booths(id uuid primary key default gen_random_uuid(), exhibition_id uuid not null references public.exhibitions(id) on delete cascade, booth_code text not null, area_sqm numeric(10,2) not null default 0, price numeric(12,2) not null default 0, status text not null default 'available', exhibitor_id uuid references public.exhibitors(id) on delete set null, reservation_expires_at timestamptz, notes text, unique(exhibition_id,booth_code));
create table public.projects(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id) on delete set null, name text not null, owner_id uuid references auth.users(id), status public.record_status not null default 'active', start_date date, due_date date, budget numeric(12,2) not null default 0, description text, created_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id) on delete set null, company_name text not null, contact_name text, email text, phone text, country text, source text, stage text not null default 'new', assigned_to uuid references auth.users(id), next_followup_at timestamptz, notes text, created_at timestamptz not null default now());
create table public.invoices(id uuid primary key default gen_random_uuid(), invoice_number text not null unique, exhibition_id uuid references public.exhibitions(id) on delete set null, exhibitor_id uuid references public.exhibitors(id) on delete set null, issue_date date not null default current_date, due_date date, currency char(3) not null default 'AED', subtotal numeric(12,2) not null default 0, tax numeric(12,2) not null default 0, total numeric(12,2) generated always as (subtotal+tax) stored, amount_paid numeric(12,2) not null default 0, status text not null default 'unpaid', notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.invoice_items(id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.invoices(id) on delete cascade, description text not null, quantity numeric(10,2) not null default 1, unit_price numeric(12,2) not null default 0, tax_rate numeric(5,2) not null default 0, line_total numeric(12,2) generated always as (quantity*unit_price*(1+tax_rate/100)) stored);
create table public.payments(id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.invoices(id) on delete cascade, payment_date date not null default current_date, amount numeric(12,2) not null check(amount>0), method text, reference text, received_by uuid references auth.users(id), notes text, created_at timestamptz not null default now());
create table public.expenses(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id) on delete set null, project_id uuid references public.projects(id) on delete set null, category text not null, description text, amount numeric(12,2) not null default 0, currency char(3) not null default 'AED', expense_date date not null default current_date, vendor text, receipt_path text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.service_orders(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id) on delete cascade, exhibitor_id uuid references public.exhibitors(id) on delete set null, booth_id uuid references public.booths(id) on delete set null, order_number text not null unique, service_type text not null, description text, quantity numeric(10,2) not null default 1, unit_price numeric(12,2) not null default 0, status text not null default 'requested', assigned_to uuid references auth.users(id), due_at timestamptz, completed_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.inventory_items(id uuid primary key default gen_random_uuid(), sku text unique, name text not null, category text, quantity_on_hand numeric(10,2) not null default 0, unit text not null default 'pcs', reorder_level numeric(10,2) not null default 0, unit_cost numeric(12,2) not null default 0, storage_location text, created_at timestamptz not null default now());
create table public.assets(id uuid primary key default gen_random_uuid(), asset_tag text unique, name text not null, category text, condition text, assigned_to uuid references auth.users(id), location text, purchase_date date, purchase_cost numeric(12,2) default 0, notes text, created_at timestamptz not null default now());
create table public.activities(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), entity_type text not null, entity_id uuid, action text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table public.company_settings(id uuid primary key default gen_random_uuid(), company_name text not null default 'VEGA Intertrade', address text, logo_path text, default_currency char(3) not null default 'AED', tax_number text, invoice_prefix text not null default 'VEGA-', updated_at timestamptz not null default now());
-- RLS: authenticated team users share workspace records; role restrictions govern financial write access.
do $$ declare t text; begin foreach t in array array['profiles','exhibitions','exhibitors','booths','projects','leads','invoices','invoice_items','payments','expenses','service_orders','inventory_items','assets','activities','notifications','company_settings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "Team can view profiles" on public.profiles for select to authenticated using (true);
create policy "Admin manages profiles" on public.profiles for all to authenticated using (public.is_admin()) with check (public.is_admin());
-- All signed-in workspace members can read and create operational records. Financial tables write limited to admin/accountant.
create policy "Team read exhibitions" on public.exhibitions for select to authenticated using (true);
create policy "Admin staff manage exhibitions" on public.exhibitions for all to authenticated using (public.current_role() in ('admin','staff')) with check (public.current_role() in ('admin','staff'));
create policy "Team read exhibitors" on public.exhibitors for select to authenticated using (true);
create policy "Team manage exhibitors" on public.exhibitors for all to authenticated using (public.current_role() in ('admin','staff')) with check (public.current_role() in ('admin','staff'));
create policy "Team read booths" on public.booths for select to authenticated using (true);
create policy "Team manage booths" on public.booths for all to authenticated using (public.current_role() in ('admin','staff')) with check (public.current_role() in ('admin','staff'));
create policy "Team read projects leads services inventory assets" on public.projects for select to authenticated using(true);
create policy "Team manage projects" on public.projects for all to authenticated using(public.current_role() in ('admin','staff')) with check(public.current_role() in ('admin','staff'));
create policy "Team read leads" on public.leads for select to authenticated using(true);
create policy "Team manage leads" on public.leads for all to authenticated using(public.current_role() in ('admin','staff')) with check(public.current_role() in ('admin','staff'));
create policy "Team read service orders" on public.service_orders for select to authenticated using(true);
create policy "Team manage service orders" on public.service_orders for all to authenticated using(public.current_role() in ('admin','staff')) with check(public.current_role() in ('admin','staff'));
create policy "Team read inventory" on public.inventory_items for select to authenticated using(true);
create policy "Team manage inventory" on public.inventory_items for all to authenticated using(public.current_role() in ('admin','staff')) with check(public.current_role() in ('admin','staff'));
create policy "Team read assets" on public.assets for select to authenticated using(true);
create policy "Team manage assets" on public.assets for all to authenticated using(public.current_role() in ('admin','staff')) with check(public.current_role() in ('admin','staff'));
create policy "Financial read" on public.invoices for select to authenticated using(true);
create policy "Financial manage invoices" on public.invoices for all to authenticated using(public.current_role() in ('admin','accountant')) with check(public.current_role() in ('admin','accountant'));
create policy "Financial read items" on public.invoice_items for select to authenticated using(true);
create policy "Financial manage items" on public.invoice_items for all to authenticated using(public.current_role() in ('admin','accountant')) with check(public.current_role() in ('admin','accountant'));
create policy "Financial read payments" on public.payments for select to authenticated using(true);
create policy "Financial manage payments" on public.payments for all to authenticated using(public.current_role() in ('admin','accountant')) with check(public.current_role() in ('admin','accountant'));
create policy "Financial read expenses" on public.expenses for select to authenticated using(true);
create policy "Financial manage expenses" on public.expenses for all to authenticated using(public.current_role() in ('admin','accountant')) with check(public.current_role() in ('admin','accountant'));
create policy "Users read own notifications" on public.notifications for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy "Users update own notifications" on public.notifications for update to authenticated using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "Team read activities" on public.activities for select to authenticated using(true);
create policy "Team insert activities" on public.activities for insert to authenticated with check(actor_id=auth.uid());
create policy "Team read company settings" on public.company_settings for select to authenticated using(true);
create policy "Admin manage company settings" on public.company_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());

-- Extended VEGA cloud ERP feature schema (companies, compliance, event workflows, accounting, HR, comms).
create table public.companies(id uuid primary key default gen_random_uuid(), name text not null, registration_number text, country text, address text, email text, phone text, whatsapp text, trade_license_path text, license_issue_date date, license_expiry_date date, created_at timestamptz not null default now());
alter table public.exhibitors add column if not exists company_id uuid references public.companies(id) on delete set null;
alter table public.exhibitors add column if not exists passport_path text;
alter table public.exhibitors add column if not exists visa_path text;
alter table public.exhibitors add column if not exists passport_expiry date;
alter table public.exhibitors add column if not exists visa_expiry date;
alter table public.exhibitors add column if not exists ai_lead_score numeric(5,2) default 0;
alter table public.exhibitors add column if not exists commission_rate numeric(5,2) default 0;
create table public.sponsorships(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id) on delete cascade, company_id uuid references public.companies(id) on delete set null, sponsor_name text not null, tier text, amount numeric(12,2) default 0, currency char(3) default 'AED', deliverables jsonb default '[]', status text default 'prospect', created_at timestamptz default now());
create table public.booth_reservations(id uuid primary key default gen_random_uuid(), booth_id uuid not null references public.booths(id) on delete cascade, company_id uuid references public.companies(id) on delete set null, exhibitor_id uuid references public.exhibitors(id) on delete set null, reservation_status text not null default 'reserved', reserved_at timestamptz not null default now(), expires_at timestamptz not null, approved_by uuid references auth.users(id), approved_at timestamptz, created_at timestamptz default now());
create table public.exhibition_checklists(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id) on delete cascade, title text not null, milestone_date date, assigned_to uuid references auth.users(id), completed_at timestamptz, status text default 'pending', notes text, created_at timestamptz default now());
create table public.quotations(id uuid primary key default gen_random_uuid(), quote_number text unique not null, company_id uuid references public.companies(id), exhibitor_id uuid references public.exhibitors(id), exhibition_id uuid references public.exhibitions(id), currency char(3) default 'AED', subtotal numeric(12,2) default 0, vat numeric(12,2) default 0, total numeric(12,2) default 0, valid_until date, status text default 'draft', pdf_path text, created_at timestamptz default now());
create table public.contracts(id uuid primary key default gen_random_uuid(), contract_number text unique not null, company_id uuid references public.companies(id), exhibition_id uuid references public.exhibitions(id), contract_path text, signature_provider text, signed_at timestamptz, status text default 'draft', created_at timestamptz default now());
create table public.credit_notes(id uuid primary key default gen_random_uuid(), credit_note_number text unique not null, invoice_id uuid references public.invoices(id), amount numeric(12,2) not null, reason text, status text default 'draft', created_at timestamptz default now());
create table public.installments(id uuid primary key default gen_random_uuid(), invoice_id uuid references public.invoices(id) on delete cascade, installment_number int not null, amount numeric(12,2) not null, due_date date not null, paid_amount numeric(12,2) default 0, status text default 'pending');
create table public.exchange_rates(id uuid primary key default gen_random_uuid(), base_currency char(3) not null, quote_currency char(3) not null, rate numeric(18,8) not null, effective_date date not null, source text, unique(base_currency,quote_currency,effective_date));
create table public.accounts(id uuid primary key default gen_random_uuid(), account_code text unique, name text not null, account_type text not null, currency char(3) default 'AED', opening_balance numeric(14,2) default 0, active boolean default true);
create table public.account_transactions(id uuid primary key default gen_random_uuid(), account_id uuid references public.accounts(id), exhibition_id uuid references public.exhibitions(id), txn_date date not null default current_date, description text, debit numeric(14,2) default 0, credit numeric(14,2) default 0, reference text, created_at timestamptz default now());
create table public.suppliers(id uuid primary key default gen_random_uuid(), name text not null, contact_name text, email text, phone text, country text, category text, tax_number text, created_at timestamptz default now());
create table public.purchase_orders(id uuid primary key default gen_random_uuid(), po_number text unique not null, supplier_id uuid references public.suppliers(id), exhibition_id uuid references public.exhibitions(id), amount numeric(12,2) default 0, currency char(3) default 'AED', requested_by uuid references auth.users(id), approved_by uuid references auth.users(id), status text default 'draft', due_date date, created_at timestamptz default now());
create table public.issue_reports(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id), booth_id uuid references public.booths(id), reported_by uuid references auth.users(id), title text not null, description text, photo_paths jsonb default '[]', priority text default 'normal', status text default 'open', assigned_to uuid references auth.users(id), created_at timestamptz default now(), resolved_at timestamptz);
create table public.staff_profiles(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, department text, job_title text, phone text, sales_target numeric(12,2) default 0, commission_rate numeric(5,2) default 0, active boolean default true);
create table public.staff_schedules(id uuid primary key default gen_random_uuid(), staff_id uuid references public.staff_profiles(id) on delete cascade, shift_date date not null, start_time time, end_time time, location text, status text default 'scheduled');
create table public.attendance(id uuid primary key default gen_random_uuid(), staff_id uuid references public.staff_profiles(id) on delete cascade, attendance_date date not null, check_in timestamptz, check_out timestamptz, status text default 'present', unique(staff_id,attendance_date));
create table public.chat_messages(id uuid primary key default gen_random_uuid(), sender_id uuid references auth.users(id), recipient_id uuid references auth.users(id), channel_id text default 'team', message text not null, read_at timestamptz, created_at timestamptz default now());
create table public.warehouses(id uuid primary key default gen_random_uuid(), name text not null, location text, manager_id uuid references auth.users(id), created_at timestamptz default now());
create table public.stock_movements(id uuid primary key default gen_random_uuid(), item_id uuid references public.inventory_items(id), warehouse_id uuid references public.warehouses(id), movement_type text not null, quantity numeric(12,2) not null, exhibition_id uuid references public.exhibitions(id), reference text, moved_by uuid references auth.users(id), moved_at timestamptz default now());
create table public.asset_checkouts(id uuid primary key default gen_random_uuid(), asset_id uuid references public.assets(id), checked_out_to uuid references auth.users(id), exhibition_id uuid references public.exhibitions(id), checked_out_at timestamptz default now(), due_back_at timestamptz, checked_in_at timestamptz, condition_out text, condition_in text, notes text);
create table public.automation_rules(id uuid primary key default gen_random_uuid(), name text not null, trigger_event text not null, conditions jsonb default '{}', actions jsonb default '[]', active boolean default true, created_by uuid references auth.users(id), created_at timestamptz default now());
create table public.email_campaigns(id uuid primary key default gen_random_uuid(), name text not null, subject text, body text, audience_filter jsonb default '{}', scheduled_at timestamptz, sent_at timestamptz, status text default 'draft', created_by uuid references auth.users(id), created_at timestamptz default now());
create table public.approvals(id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, requested_by uuid references auth.users(id), approver_id uuid references auth.users(id), status text default 'pending', comments text, requested_at timestamptz default now(), decided_at timestamptz);
create table public.audit_log(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, before_data jsonb, after_data jsonb, ip_address inet, created_at timestamptz default now());
create table public.user_devices(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, device_label text, last_ip inet, last_seen timestamptz default now(), trusted boolean default false);
create table public.document_expiry_alerts(id uuid primary key default gen_random_uuid(), company_id uuid references public.companies(id), exhibitor_id uuid references public.exhibitors(id), document_type text not null, expires_on date not null, notified_at timestamptz, status text default 'pending');
-- Enable RLS on newly introduced tables; authenticated team access is the baseline, admin-only control for settings/audit.
do $$ declare t text; begin foreach t in array array['companies','sponsorships','booth_reservations','exhibition_checklists','quotations','contracts','credit_notes','installments','exchange_rates','accounts','account_transactions','suppliers','purchase_orders','issue_reports','staff_profiles','staff_schedules','attendance','chat_messages','warehouses','stock_movements','asset_checkouts','automation_rules','email_campaigns','approvals','audit_log','user_devices','document_expiry_alerts'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for select to authenticated using (true)',t||'_team_read',t); execute format('create policy %I on public.%I for insert to authenticated with check (public.current_role() in (''admin'',''accountant'',''staff''))',t||'_team_insert',t); execute format('create policy %I on public.%I for update to authenticated using (public.current_role() in (''admin'',''accountant'',''staff'')) with check (public.current_role() in (''admin'',''accountant'',''staff''))',t||'_team_update',t); execute format('create policy %I on public.%I for delete to authenticated using (public.is_admin())',t||'_admin_delete',t); end loop; end $$;
